	@Test
	public void imresizeTest() {
		checkArray(A_7x6, ImResize.imresizeBicubic(A, 7, 6), 1e-12);
		checkArray(A_3x2, ImResize.imresizeBicubic(A, 3, 2), 1e-12);
		checkArray(A_6x3, ImResize.imresizeBicubic(A, 6, 3), 1e-12);
		//resizing to the same size should return the same image
		checkArray(A, ImResize.imresizeBicubic(A, 4, 5), 1e-15);
	}

	@Test
	public void imadjustTest() {
		double[] lims = SpecTransform.stretchlim(C, 0.01, 0.99);
		assertArrayEquals(C_LIMS, lims, 1e-15);
		checkArray(C_ADJUST, SpecTransform.imadjust(C, lims[0], lims[1]), 1e-12);

		lims = SpecTransform.stretchlim(E, 0.01, 0.99);
		assertArrayEquals(E_LIMS, lims, 1e-15);
		checkArray(E_ADJUST, SpecTransform.imadjust(E, lims[0], lims[1]), 1e-12);

		//a flat image is not adjusted
		double[] flatLims = SpecTransform.stretchlim(new double[][] {{0.5, 0.5}, {0.5, 0.5}}, 0.01, 0.99);
		assertEquals(0, flatLims[0]);
		assertEquals(1, flatLims[1]);
	}

	private static void checkArray(double[][] expected, double[][] actual, double tol) {
		assertEquals(expected.length, actual.length);
		for (int i = 0; i < expected.length; i++) {
			assertArrayEquals(expected[i], actual[i], tol, "row " + i);
		}
	}

